using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SadisticPlanAchievementData", menuName = "Data/Achievements/SadisticPlanAchievementData")]
public class SadisticPlanAchievementData : AchievementData
{
	public void SadisticPlanUnlock(CorruptedAnimalCorruptionStats corruptedAnimalCorruptionStats, GameObject source)
	{
		if (IsUnlocked())
		{
			return;
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 2, delegate
		{
			if (corruptedAnimalCorruptionStats.IsDefeated() && source == corruptedAnimalCorruptionStats.gameObject)
			{
				Unlock();
			}
		});
	}
}
